quests[38723] = { id = 38723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop Gul'dan!", description = "After his defeat at the Black Temple, we brought Illidan's lifeless body here, to be interred forever within the Vault of the Wardens.\n\nGul'dan has found his way through our defenses and is trying to steal the Betrayer's corpse.\n\nEven in death, Illidan's body can be used by the Burning Legion. Gul'dan CANNOT succeed.", completion = "Excellent. You have absorbed the powers of these brutes. Look how strong you have grown!", objectives = "Enter the Vault of the Betrayer, kill Crusher and Sledge, and take their fel power.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38724] = { id = 38724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brotherly Love", description = "Maiev will be somewhere in the prison. I found her discarded armor on my way here.\n\nLet's split up to search the cells more quickly.\n\nWe must find her.", completion = "<Maiev's face is bruised, her lips cracked, and her body covered in scars. She looks thin and ragged, but she moves with purpose.>\n\nFor weeks they tried to break me. Amateurs!\n\nI kept my silence. I counted the minutes, measured their steps, and listened to the voices beyond my cell.\n\nI have been waiting for my chance to escape, and to strike back at my captors.\n\nNow, you bring my armor AND my blade. My salvation will be followed by bloodshed.\n\n<Maiev smiles.>", objectives = "Find Maiev Shadowsong in Black Rook Prison.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38725] = { id = 38725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Foul Creche", description = "One of the demons that I interrogated revealed a particularly juicy bit of information. Apparently, there's an imp mother in the volcano that scribes Legion secrets.\n\nKor'vas has gone out to find that demon and bring those secrets back for us.", completion = "{name}. I've found her.", objectives = "Meet up with Kor'vas Bloodthorn at the Foul Creche.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38726] = { id = 38726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Magwia" }
quests[38727] = { id = 38727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stop the Bombardment", description = "Jace's wards are not going to hold out much longer. We need someone to go out there and make sure those Legion devastators are destroyed.\n\n<Kayn pointedly looks at you with his spectrally-enhanced vision.>", completion = "True leadership is hard to come by. Leading from the front is an even rarer trait.\n\nWe are just about ready to assail Brood Queen Tyranna's command center.", objectives = "Destroy the Legion Devastators.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38728] = { id = 38728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Keystone", description = "{name}, Brood Queen Tyranna is just ahead in the command chamber. The others already charged in. She has the Sargerite Keystone in her possession.\n\nFinally, the object of all our sacrifice is at hand.", progress = "{name}, are you ready?", completion = "Now that we have the keystone in our possession, there is just one last thing left to do...", objectives = "Kill Brood Queen Tyranna and take the Sargerite Keystone. Then, join the others down-below in the portal chamber.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38729] = { id = 38729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Black Temple", description = "Quickly, {name}, use the Sargerite Keystone.\n\nWe must get back to the Black Temple before it is too late!", completion = "<As you invoke the power of the Sargerite Keystone, the fel portal is suffused with an otherworldly energy.\n\nIt is time to return triumphant to the Black Temple and aid Lord Illidan in repelling the invading forces from Azeroth and Shattrath City.>", objectives = "Use the Sargerite Keystone to activate the Fel Portal and return to the Black Temple.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
