quests[38736] = { id = 38736, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: IH Elite Sniper" }
quests[38737] = { id = 38737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An End To War", description = "It appears that the great Ancient of War, Ironbranch, has fallen to the Nightmare.\n\nIt pains me greatly to ask this of you, but Ironbranch must be put to rest.\n\nIn life, he once stood vigil in Shala'nir as a protector of the world tree. In death, my dear friend is no more than a destructive weapon that will be used to cause even more violence.\n\nHe must be slain before he does more harm to Val'sharah.\n\nIn my heart, I know that he would thank you for this mercy...", objectives = "Defeat Ironbranch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
