quests[38742] = { id = 38742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Crazy BH Chief Skull" }
quests[38743] = { id = 38743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Val'sharah", description = "Malfurion, my love.... My heart breaks for him, but I cannot follow where he goes.\n\nI have sworn myself to Elune, my goddess, to defend her temples and lands with all that I am. I cannot stand by while my order is in danger.\n\nMay she keep you in her graces, Malfurion.\n\n<Tyrande turns away, eyes glistening with tears.>", completion = "This shall be remembered as one of the darkest days in the history of our world. But hope remains. Elune's light has strengthened our resolve.", objectives = "Defend the Temple of Elune.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38744] = { id = 38744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Stormheim - Treasure 030 - Statue - ZTO" }
quests[38745] = { id = 38745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hard Lessons", description = "Please understand, stranger, that I am a being of peace. I have discarded any vengeful nature long, long ago.\n\nIn my youth, however, many hard lessons were learned through discipline. When applied wisely and properly, discipline can be a great teacher and shaper of character.\n\nIt is in the spirit of wisdom and guidance that I would have you teach these harpies a memorable lesson.", objectives = "Burn 5 Harpy Nests and Break 5 Harpy Eggs in the Wretched Grove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
