quests[38753] = { id = 38753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Demon's Trail", description = "Malfurion is nearby. I can sense him.\n\nSearch the summit of Andu'talah while I continue to scour the forest.\n\nBe swift, {name}. Time is of the essence!", completion = "My husband, Malfurion, what has become of him?!\n\nAnswer me!", objectives = "Find Malfurion Stormrage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
