quests[38759] = { id = 38759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Set Them Free", description = "Cyana went down to the Molten Shore. She was going to help some of the demon hunters who came in through the gateway ahead of us. Instead, she got herself into trouble.\n\nThis inquisitor revealed they're being held prisoner by some new type of demon called a 'jailer'. The thing sucks the souls out of its victims. I doubt they can hold out much longer.", progress = "Some of our demon hunters are missing. Did you see them back on the Molten Shore?", completion = "Their souls were being sucked dry by a jailer demon?\n\nThe Burning Legion in this place is far more powerful and brutal than we have ever seen before.", objectives = "Several of your demon hunters are in trouble. Get the Soulwrought Key to set them free.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38760] = { id = 38760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Captain's Booty 1" }
