quests[38765] = { id = 38765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enter the Illidari: Shivarra", description = "Our Shivarra demonesses are waiting at the Black Temple. It's a gamble bringing them here... they used to be part of the Burning Legion after all. But, they are some of the most powerful in Lord Illidan's arsenal.\n\n<Jace looks at you for a long moment.>\n\nI have a feeling that the ultimate sacrifice is going to have to be made in order to summon them in.", completion = "Grim. But demon hunters are no strangers to sacrifice. We have given everything to become what we are.\n\nThe Legion will fall. We await your orders, {name}.", objectives = "Feed a powerful soul into the Legion Gateway Activator and then use it to summon in your Shivarra forces.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38766] = { id = 38766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Before We're Overrun", description = "The doomguard commander and his queen must be dealt with. His eredar are summoning in a huge number of reinforcements.\n\nWe need to put an end to him before the Legion overruns our new foothold up in the volcano!\n\nAs an added benefit, you can steal his demonic power.", completion = "Already, the flow of demons from below has slowed to a trickle.\n\nI can sense the doom guard's energy. You have become more powerful.", objectives = "Slay Doom Commander Beliash and take his power for your own.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38767] = { id = 38767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nightmaul" }
