quests[38776] = { id = 38776, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Sacrificial Blade" }
quests[38777] = { id = 38777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leystone Deposit Sample", description = "This ore looks like nothing you've seen before.\n\nA mystical sheen moves through the metal in complex, unpredictable patterns. Your trainer in Dalaran would certainly like to see this.", progress = "What's that you've got there, boy?", completion = "It's so light. So pretty, too! Reminds me of elementium, a bit.\n\nIf you see any more ore like this, try and strike it with the grain. You'll waste much less of it.", objectives = "Bring the Leystone Deposit Sample to Mama Diggs in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38778] = { id = 38778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turn the Keys", description = "My roots wither... my branches die...\n\nThe Bonespeakers, they seek to silence the Runewood.  The runestones are the key...\n\nTurn the stones... release my bonds...", progress = "My shackles remain...", completion = "So it was your footsteps I felt upon my woods as the runestones released their grip? \n\nYou have my thanks, outsider.", objectives = "Activate the Runestones within the Runewood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38779] = { id = 38779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Hidden BH Chest" }
quests[38780] = { id = 38780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - River - Vignette: Thondrax - TRACKING - twh" }
quests[38781] = { id = 38781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 016- Andu'talah - twh" }
quests[38782] = { id = 38782, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 017 - Darkgrove Cavern - twh" }
quests[38783] = { id = 38783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 018 - Andu'talah - twh" }
quests[38784] = { id = 38784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leystone Seam Sample", description = "This ore has clearly absorbed some of the latent ley energies within the Broken Isles. It is cool to the touch, and reflects light in odd, playful angles.\n\nYour trainer in Dalaran should analyze this.", progress = "What've ye brought me now?", completion = "Look at that! She's a lovely one, isn't she?\n\nTreat this type of ore with care, lad. No fat-muscle shoulder swings necessary - just a gentle tap on the right spot and you'll extract much more ore than a beginner.", objectives = "Bring the Leystone Seam Sample to Mama Diggs in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38785] = { id = 38785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Living Leystone Sample", description = "This is no normal leystone. It is much livelier, shimmering in complex, enthralling patterns. It is easy to stare at.\n\nYour trainer in Dalaran would certainly like to have a look at this.", progress = "Oh, my...", completion = "Now isn't that somethin'? You got this offa one of those rocky creatures down there?\n\nLooks like ye only brought me a bit o' the torso, though. Next time, make sure to get the arms and head too. Lots o' good meat in there.", objectives = "Bring the Living Leystone Sample to Mama Diggs in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38786] = { id = 38786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where Respect is Due", description = "Leystone is a sensitive ore. Our smiths can coax great power out of it, but as miners, we must treat it with respect, or else its power will retreat inward.\n\n<The tauren hands you what appears to be a GLASS mining pick.>\n\nThe next time you mine some leystone ore, use this pick. It will break if you strike too hard. THIS is the respect that leystone requires.", progress = "You haven't broken my pick, have you?", completion = "You've learned much, {name}.\n\nStay a while. I have a story for you.", objectives = "Mine for leystone 35 times while using Ronos's Glass Pick.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38787] = { id = 38787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Legend of Rethu Ironhorn", description = "A long, long time ago, a tauren by the name of Rethu entered this land. His exploits paved the road that all miners walk.\n\nIf you wish to learn more about mining, you must first learn about Rethu.", progress = "Listen well, {name}.", completion = "Echoes of Rethu's time in this land still remain, {name}. Be on the lookout for his influence when you are out in the field.", objectives = "Speak with Ronos Ironhorn to learn the tale of Rethu Ironhorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38788] = { id = 38788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Magic Brazier" }
quests[38789] = { id = 38789, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rethu's Journal", description = "Tucked in between a few pieces of rubble, a scrap of paper catches your eye.\n\nMining carefully, you uncover the tattered remains of an old scroll. The tauren handwriting is archaic, but one word catches your eye:\n\n\"Rethu\".", progress = "Greetings, miner. What have you here?", completion = "This... this cannot be! A piece of Rethu's own mining log!\n\nLook here, miner... it details a leystone mining technique he was working on...", objectives = "Bring the Torn Journal Page to Ronos Ironhorn in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38790] = { id = 38790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rethu's Pick", description = "This seam has been mined before - it bears the telltale diagonal ruts of a miner's pick.\n\nLooking down, that pick now lays on the ground - handle broken, pick-point dulled with use and years.\n\nCarved into the haft is a familiar name:\n\n\"Rethu\"", progress = "What is that you hold, miner?", completion = "Rethu's own mining pick...\n\nWell, one of them, anyhow. Stories say he went through them almost weekly.\n\nStill, I've never seen one with my own eyes. Look at the wear on the blade, miner. The angles he used... the strength with which he struck: we could learn much from studying this artifact.", objectives = "Bring the Battered Mining Pick to Ronos Ironhorn in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38791] = { id = 38791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rethu's Horn", description = "The corpse of the rocky beast yielded an unusual treasure: a battered chunk of tauren's horn.\n\nIt is clearly very, very old, but something about its color and curve reminds you of Ronos Ironhorn at the Ironhorn Enclave.", progress = "What... what is that, miner?", completion = "This... this could not be...\n\nThis is from a member my tribe, {name}. Where did you find this?\n\nOne of the first stories we ever learn about Rethu involves the day he lost his horn in battle. There is no way of knowing if this belonged to him but... but...", objectives = "Bring the Chunk of Horn to Ronos Ironhorn in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38792] = { id = 38792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rethu's Lesson", description = "You... miner... let me see your pick a moment.\n\n<The tauren spirit eyes your mining equipment.>\n\nYou remind me of myself, when I once walked this land. Savor these moments, miner. They cannot last forever.\n\n<With a bow, the spirit disappears.>", completion = "You saw a spirit while out mining in the wilds?\n\nNo, I do not believe you. One mustn't spend too long out mining, it fatigues the mind. You must be seeing things.\n\nStill, something seems... different about you. You've learned something. Perhaps there's some truth to your tale after all...", objectives = "Report your encounter to Ronos Ironhorn in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38793] = { id = 38793, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rethu's Experience", description = "Miner... you... you know who I am?\n\nI see. That is good. My tribe continues to honor its roots.\n\nIf you return to the land of the Ironhorn tribe... let them know that they are looked upon with pride.", completion = "<The tauren listens as you describe your encounter with the spirit of Rethu Ironhorn.>\n\nI would not normally believe you, but... I can sense truth in your tale. You are a lucky miner.\n\nI am pleased to know that our ancestors look upon us with pride. We have chosen an admirable path.\n\nThank you, {name}.", objectives = "Report your encounter to Ronos Ironhorn in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38794] = { id = 38794, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rethu's Sacrifice", description = "Miner... speak with me a moment. I haven't much time in this place.\n\nI see you fight for your ore. I believe that is the most noble way to obtain your stone. It gives the land a fighting chance.\n\nStill, one mustn't be callous with their own life. Dig too deep, and the land will overcome you. No stone is worth the price I paid.\n\nBut that is a tale for another day...", completion = "The spirit of Rethu Ironhorn? Tell me everything he said.\n\nHe said he... dug too deep? I see. The Earthmother took him.\n\nThank you for coming to me, miner. This is a tale that the rest of the tribe must hear. We are all the wiser for it.", objectives = "Report your encounter to Ronos Ironhorn in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38795] = { id = 38795, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felslate Deposit Sample", description = "This is one nasty-looking stone.\n\nYour trainer in Dalaran should see this.", progress = "You bring me somethin' new?", completion = "This is no natural stone, miner. It stinks of demon's blood. Where'd you find this?\n\nReminds me a bit of old fel iron. Come 'ere, lemme teach you a trick or two on how to properly gather this stuff.", objectives = "Bring the Felslate Deposit Sample to Mama Diggs in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38796] = { id = 38796, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felslate Seam Sample", description = "This ore is remarkably heavy. More disturbingly, it seems to darken and hiss at your touch.\n\nPerhaps your mining trainer in Dalaran has some insights.", progress = "Looks like you've been busy down there, miner.", completion = "This came out of a cliffside seam? Remember, ye can't mine seams like ye mine deposits. Totally different thing. I'll show ye my trick.", objectives = "Bring the Felslate Seam Sample to Mama Diggs in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38797] = { id = 38797, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Living Felslate Sample", description = "Your miner's instinct is kicking in. Chunks of the infernal's corpse appear to be usable.\n\nStill, there must be a way to extract more ore from the demon's body. Perhaps your mining trainer in Dalaran will know how.", progress = "What's that?", completion = "This came from a blasted infernal? Look out, we've got mister COMBAT miner, here!\n\nSome o' this ore seems to 'ave lost its shine on the trip back, however. Next time, make sure to cut out the sword and spell wounds before ye mine it.", objectives = "Bring the Living Felslate Sample to Mama Diggs in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38798] = { id = 38798, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shred of Your Humanity", description = "To mine for felslate is to seek the very blood of demons. To improve at it, you must become part demon yourself.\n\nWhy the dirty look? You said it yourself: you're willing to make sacrifices.\n\nLuckily for you, I'm an expert in this area. I won't put you in any danger, as long as you trust me.\n\nAre you ready?", progress = "Don't waste my time, miner.", completion = "It is done.\n\nStretch it out a bit.\n\nYou may experience some stray urges to burn worlds and sow chaos for the next week or so. Do your best to resist them.", objectives = "Allow Felsmith Nal'ryssa to place three shards of felslate in your body.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38799] = { id = 38799, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkheart Thicket: Nal'ryssa's Sisters", description = "I was not the only miner in my family. I was the youngest of four sisters.\n\nI say \"was\" because the other three are gone.\n\nTwo of them went too far. They overloaded their bodies with felslate and succumbed to the will of Sargeras. They are more demon than elf, now.\n\nThe third, I have not heard from in quite some time. The last I heard, she was investigating the Darkheart Thicket.\n\nI fear she may have fallen, too - one way or the other.", progress = "Any sign of my sister?", completion = "Yes, this is my sister's ring.\n\nThe fact that you found it on a demon's corpse suggests that she has either fallen in battle or, like my other sisters, thrown in her hat with the demons themselves.\n\nThank you for bringing this to me. We don't have many spare materials here on the front lines... but I can do without these.", objectives = "Go to the Darkheart Thicket and find Lyrelle's Signet Ring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38800] = { id = 38800, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rin'thissa's Eye", description = "Oddly enveloped within the felslate deposit is a humanoid eye.\n\nIt quivers with life. You get the sense that it would blink at you if it had an eyelid.\n\nA mining expert should take a look at this.", progress = "Is... is that...?", completion = "It is. This eye once belonged to my sister, Rin'thissa.\n\nPoor fool, she cut out her own eye and replaced it with a hunk of ore. That was the tipping point... she's completely fel-maddened now.\n\nLearn from her mistake, {name}.", objectives = "Bring the Ore-Bound Eye to Felsmith Nal'ryssa in Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38801] = { id = 38801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lyrelle's Right Arm", description = "You blink and rub your eyes, but they do not deceive you. This is a woman's arm, completely enveloped within a felslate seam.\n\nThe arm is bloodless, but still twitches. Fel-colored streaks remain where veins once were.\n\nFelsmith Nal'ryssa will certainly want to see this.", progress = "Lyrelle, no...", completion = "This was my sister's. Lyrelle's.\n\nHer fate is clear now. She no longer needed that signet ring... the girl must have traded in her own mining arm for one carved out of felslate itself.\n\nAren't you glad we only used three small shards?\n\nTake this to heart, {name}: you can lose everything to greed if you don't exercise restraint. Poor Lyrelle paid that price for all of us.", objectives = "Bring the Severed Arm to Felsmith Nal'ryssa in Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38802] = { id = 38802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ondri's Still-Beating Heart", description = "What at first looked like another chunk of felslate is, in fact, a humanoid heart, encrusted in rock and filled not with blood but a vile, demonic substance.\n\nIt does not appear to belong to the beast you carved it out of... it seems that the infernal was holding it like a keepsake. Luckily your mining pick didn't hit it straight on.\n\nFelsmith Nal'ryssa will want to see this.", progress = "Ondri...", completion = "My sister Ondri was the first among us to mine, and the first among us to fall. Some Nathrezim dreadlord convinced her to replace her own heart - her heart! - with a chunk of felslate.\n\nI slew the dreadlord myself, but couldn't find the heart. This must be it.\n\nBig sister... I am sorry. Your loss will not be forgotten. We will learn from your missteps.", objectives = "Bring the Ore-Choked Heart to Felsmith Nal'ryssa in Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38803] = { id = 38803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rin'thissa", description = "My sister Nal'ryssa has her claws in you, doesn't she?\n\nThat weakling doesn't know the first thing about mining. She was always too afraid to take the leap. True knowledge comes only from the Great One, the God of Fel and Flame.\n\nYou want to truly learn how to mine? Come to Suramar's northwestern corner, and speak my name:\n\nRin'thissa.", completion = "My sister's soul rests now. I have you to thank for that.\n\nRin'thissa was always a charmer. You did well to avoid her invitations, and even better to slay her and end her demonic possession. You've learned much since we first met, {name}.", objectives = "Summon and defeat Rin'thissa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38804] = { id = 38804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lyrelle", description = "Look at you, miner. Still held back by the limitations of your fragile, decaying flesh.\n\nTo truly become one with the demon-tinged rocks of these lands, you must shed your skin and submit to a darker power.\n\nJoin us, miner. Bring your feeble body to Felsoul Hold, and speak my name:\n\nLyrelle.", completion = "Poor Lyrelle.\n\nI do not blame you for putting her down, {name}. I thank you. I hope that you would do the same to me, if I were to slip and fall down that same path.\n\nJust... try to learn something from your ordeal. Reflect on your experience. I would hate to see her sacrifice be for nothing.", objectives = "Summon and defeat Lyrelle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38805] = { id = 38805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ondri", description = "You are nothing compared to me. You think yourself hardened, experienced... heroic, even. Hah!\n\nYou have no idea what I've been through. The tortures I've endured, the sacrifices I've made. All for the sake of my trade!\n\nYes, I'm a miner, just like you. Want to learn what I have to teach? Come to the Crimson Thicket in Suramar, and speak my name:\n\nOndri.", progress = "Ondri has always heartless, one way or the other.", completion = "My sister's villainy is finally at an end.\n\nShe was always the wisest among us. Sad that she had to go out the way she did. I'm certain there was much she could have taught us.", objectives = "Summon and defeat Ondri.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38806] = { id = 38806, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infernal Brimstone Sample", description = "This ore. Smells. Horrible. It combines the odor of sulfur with all the worst parts of a rotting corpse.\n\nSomeone will probably want it for something.\n\nMaybe your mining trainer in Dalaran will take it off of your hands.", progress = "Excuse me, I must have... wait, that smell is coming from YOU?", completion = "This odiferous morsel ye've brought me... it's infernal brimstone, isn't it?\n\nAmazing.\n\nI've heard tales, but I've never actually SEEN the stuff before.\n\nI've got to study this. In the meantime, here's all I know about this rare, rare ore.", objectives = "Bring the Infernal Brimstone Sample to Mama Diggs in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38807] = { id = 38807, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infernal Brimstone Analysis", description = "In order to mine Infernal Brimstone, we first need to understand the way in which ore comes into being. I currently have three of my apprentices doing research on different ores around the world.\n\nFind Forinn Stoneheart in Deepholm, Rhol Landers in Twilight Highlands and Krul Rockhorn in Icecrown and collect any information they've gathered on the ore at those locations.", progress = "What's that you've got there, boy?", completion = "Fascinating...", objectives = "Collect the reports from Mama Diggs' apprentices in Icecrown, Deepholm and Twilight Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38808] = { id = 38808, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bjornharta", description = "The afterlife leaves the dead hungry for the delicacies of their former lives. For the vrykul kings, none such offering is prized more than Bjornharta - a celebratory feast of an engorged bear heart. \n\nThe bears of the Runewood eat well, and have long been prized for their tender meat. Hunt them and find a suitable heart of offer to the ancient rulers. They will not be able to resist such an offering.", progress = "How went the hunt, outsider?", completion = "These hearts are fat and bloody. \n\nThe slumbering rulers will not refuse an offering of Bjornharta.", objectives = "Collect 4 Engorged Bear Hearts from Voracious Bears in the Runewood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38809] = { id = 38809, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Mushroom Barrel" }
quests[38810] = { id = 38810, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dreaming Fungus", description = "So an outsider would seek to be judged by the ancient rulers of the vrykul? Curious, this. Know that they will not take to your presence kindly, stranger.\n\nIf you are so hasty to meet judgment, you can call them forth with a ritual of wakening. To complete this ritual, you will require an aromatic to burn and an offering to present.\n\nA plant grows in the Runewood that will make a suitable incense. Gather it, and I will instruct you further.", progress = "What do you bring?", completion = "Yes, these Soulcaps should be adequate for your ritual. \n\nSpeak with me once you are ready to proceed and I will guide you further.", objectives = "Collect 8 Soulcaps in the Runewood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38811] = { id = 38811, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Judgment Day", description = "You have proven resourceful thus far, stranger. As promised, I will instruct you on the ritual of wakening.\n\nFirst, you must place the offering directly atop the grave of the ruler you wish to awaken. Burn the incense so that its aroma wafts over the grave. If your offering is adequate, the ruler will rise, and you may ask your judgment.\n\nTake care, outsider. The dead vrykul kings will not enjoy being awakened from their slumber.", completion = "Ashildir's grave has been disturbed, outsider. \n\nDo you know something of this?", objectives = "Receive judgment from the ancient vrykul rulers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38812] = { id = 38812, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Shadowthrash" }
quests[38813] = { id = 38813, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orders for Your Captains", description = "All that is left is to deliver your orders to our Illidari captains. The mightiest of the Legion's forces have arrayed themselves within the volcano. But, they will not remain on the defensive for long.\n\nWe must strike first and we must strike hard.\n\nOnce we destroy them, we can fly up to the command ship, defeat Brood Queen Tyranna, and take the keystone for our own. Lord Illidan will be pleased.", progress = "Are we ready to commence the assault?", completion = "Our forces have engaged the Legion.\n\nSoon we will stand together victorious with Lord Illidan at the Black Temple.", objectives = "Brief your Illidari captains on where to attack the Burning Legion within the volcano.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38814] = { id = 38814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Mystical Staff" }
quests[38815] = { id = 38815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waking the Shieldmaiden", description = "With the rituals disrupted and her bones returned, we may be able to wrest Ashildir from the grasp of these Bonespeakers.\n\nDeeper within Haustvald, the mystics possess a special altar that can reunite the body and spirit of a fallen warrior. With this, we may be able to return Ashildir's spirit into her bones, and out of the grasp of these foul mystics.\n\nGo outsider, I will rally her guard.", completion = "Where... where am I now? \n\nI... know you...", objectives = "Use the Rune of Reformation to return Ashildir's spirit to her bones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38816] = { id = 38816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Bonespeakers", description = "The crimes of these ritualists must not go unpunished, but we cannot be their executioners. The rune magic they practice grants them untold power over the dead.\n\nYou, however, are not dead, and I can sense great power from you. Take the fight to these heretics, and show Ashildir that you are truly worthy of her judgment!", completion = "Your glorious battle honors the Valkyra queen.", objectives = "Defeat 15 Bonespeaker vrykul or their allies in Haustvald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38817] = { id = 38817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regal Remains", description = "So you seek the judgment of the queen of the Valkyra? This must be your fault!\n\nThe Bonespeakers of Haustvald have committed an atrocity and stolen Ashildir's bones. They must have done this to keep an outsider from completing the trials. You must not let this stand!\n\nEnter Haustvald and retrieve her remains. I hope, for your sake, that Ashildir is in a forgiving mood.", progress = "Were you able to recover her remains?", completion = "The treachery of the Bonespeakers knows no limit. \n\nTheir rituals seek to sunder the very essence of our queen, but we will use their own magic to return her to us!", objectives = "Collect 8 Ashildir's Bones in Haustvald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38818] = { id = 38818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Judgment", description = "In my fragmented state, I captured glimpses of a hero meting out justice to the corrupted mystics of Haustvald. I see now, this hero was you, {class}. \n\nI know you seek my judgment, but my spirit is still fragmented. As we speak,  Runeseer Faljar is calling upon dark, forbidden magics in an attempt to banish my spirit to Helheim. If he succeeds, your trial will be lost.\n\nMy connection here is fading. Go, there is little time!", completion = "I cannot believe this fate... \n\nI am sorry, outsider, for I had underestimated Faljar's power.\n\nThat he could banish us here... is unthinkable.", objectives = "Defeat Runeseer Faljar in Haustvald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38819] = { id = 38819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Their Numbers Are Legion", description = "Yes, those devastators must be silenced, but there's also a great deal more to be done.\n\nDespite the odds, we're counting on you. The Brood Queen's primary leaders are in control of the volcano. They must be killed. We must smash the Legion and do anything else necessary to achieve absolute victory.", completion = "I am in complete agreement. From where I'm standing, you utterly decimated their forces.\n\nWhat do you think? Are we ready to fly up to that command center and take the Sargerite Keystone?", objectives = "Wage war upon the Brood Queen's Court and the Burning Legion within the greater Inferno Peak area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38820] = { id = 38820, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Captain Grok'mar" }
quests[38821] = { id = 38821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: The Commander's Shield" }
quests[38822] = { id = 38822, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Arcane Wand" }
quests[38823] = { id = 38823, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Runes that Bind", description = "The stone tablet here describes a ritual where a powerful spirit can be broken into weaker pieces by binding them to special runestones. It looks like the Bonespeakers may be using this very ritual to weaken the spirit of Ashildir.\n\nIt may be impossible to summon her with her spirit so weakened. The rituals must be stopped.", completion = "These mystics have gone to great lengths to weaken Ashildir. \n\nWe must hope that her spirit is strong enough for the wakening.", objectives = "Destroy the Ritual Stones to stop the rituals binding Ashildir's spirit in Haustvald.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38825] = { id = 38825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blazing Crusader" }
quests[38827] = { id = 38827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Will Be Done", description = "Lord Grayson Shadowbreaker has drawn a rough map of what we know of the Broken Isles.\n\nYou should speak with him at once - he can best advise you on where we should first strike against the Legion.", sourceObjective = "Speak to Lord Grayson Shadowbreaker.", sourceObjectiveStatus = "unverified-source-field" }
quests[38833] = { id = 38833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Art of Demonsteel", description = "The Firmament Stone is one of the few anvils beneath the sky that can tolerate the hammer strikes necessary to craft demonsteel.\n\nHere, I will show you.\n\nTwo parts leystone, one part felslate. No heat, no tempering, just pure strength and finesse.\n\nTry it. I will coach you.", completion = "There you have it... demonsteel.\n\nWelcome to the next level of smithing, {name}.", objectives = "Work with Muirn Ironhorn to craft a Demonsteel Bar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38834] = { id = 38834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Fray", description = "The Burning Legion has beaten us here, but so too have the Illidari. It looks like the demon hunters are holding their own, but just barely.\n\nCome, let's put that weapon of yours to use. I'll figure out our next move while you crush the Legion.", completion = "The two of you are a welcome sight. We pushed the demons out of these ruins, but they are stronger than any we have encountered before.\n\nYour help is appreciated. If we do not crush this Legion invasion now, they will overrun Azsuna and then the rest of the Broken Isles.", objectives = "Speak with the lead demon hunter at Illidari Stand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38836] = { id = 38836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aktar's Post" }
quests[38837] = { id = 38837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Mordvigbjorn" }
quests[38838] = { id = 38838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Enraged Earthservant" }
quests[38839] = { id = 38839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Done with Waiting", description = "Mom got a message and said blood called for blood. She told me to wait here while she went out, but it's been two weeks since then. I'm tired of waiting.\n\nI'll stay home if you go find her. She said she was going to the cliffs far to the south.", sourceObjective = "Travel to the southern cliffs of Val'sharah and speak to Makra Knifewhisper.", sourceObjectiveStatus = "unverified-source-field" }
quests[38840] = { id = 38840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fishy Business", description = "Makrura are massing down by the shore, and far too many of them seem to practice water magic.\n\nI think once they've got enough spellcasters, they're planning to summon a massive wave.", objectives = "Kill 3 Murktide Wavecallers on the southern coast of Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38841] = { id = 38841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die, Fish-People", description = "Makrura are massing down by the shore, and far too many of them seem to practice water magic. I think they're planning to summon a massive wave.\n\nAlso, I've come a long way, and I'm out of supplies. I'm so hungry, I could eat almost anything. Even the makrura you kill. Just cut the heads off first.", objectives = "Bring 3 Intact Murktide Tails to Makra Knifewhisper on the southern cliffs of Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38842] = { id = 38842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faerie Fracas" }
quests[38844] = { id = 38844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rally the Wilds Buff Received" }
