quests[38855] = { id = 38855, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "zzDEPRECATEDzz Fighting on the Front", description = "[TEMP] While you are here, maybe you could help out a little? Normally you'd get this at the objective map in Lion's Watch. Please help out here.", objectives = "[TEMP] Complete the Iron Front Daily.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38856] = { id = 38856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holy Retribution", description = "I fell in what you now call Tirisfal Glades at the claws of two of Yogg'Saron's most powerful lieutenants... the C'Thraxi. I was able to slay one in my death throes - Az'jtal.\n\nNow, the dark forces deep beneath Azeroth have begun to usher Az'jtal once again into this world. You must go to Tyr's Fall and strike Az'jtal down again before it can fully manifest.\n\nOnly once this deed is done may you receive my blessing upon the Ashbringer.You will learn:", objectives = "Strike down Az'jtal at Tyr's Fall in Tirisfal Glades.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38857] = { id = 38857, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Favor for Mr. Shackle", description = "Throm'ka, {class}. My name is Seska. I represent a... trading company. As you can see, I've fallen victim to these giants and their naga allies.\n\nThree of my associates were also captured while surveying this cove. I'm certain that my employer, Mr. Shackle, would be most grateful if you could procure their release.", progress = "You say your name is {name}? Welcome to our humble den. Seska is very grateful for her freedom.\n\nYou haven't perchance seen the rest of my people?", completion = "Excellent, my good sir. I cannot thank you enough for the freedom of my people. Rosh is especially appreciative.\n\n<Gentle Rosh grunts.>\n\nPerhaps you and I can do some more business together.", objectives = "Free Cleave Thunderhill, Gentle Rosh, and Grace the Green.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38861] = { id = 38861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 019 - Lunarwing Shallows - twh" }
quests[38862] = { id = 38862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thieving Thistleleaf", description = "Why the Thistleleaf are collecting the Lunarwing eggs is anyone's guess, but you can be sure it's not to give them a loving home.\n\nSaylanna Riverbreeze will know what to do with these.", progress = "Gather as many eggs as you can and bring them back to me. I will keep them safe.", completion = "Until I can discover what is vexing the Thistleleaf, I'll have to look after the Lunarwing eggs. At least I know they will be safe.", objectives = "Collect 5 Stolen Lunarwing Eggs in the Lunarwing Shallows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38863] = { id = 38863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Partially Mined Apexis Crystal" }
