quests[38866] = { id = 38866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle At The Iron Front" }
quests[38867] = { id = 38867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inspiration Strikes", description = "The blood of this creature glows with magical energy. It doesn't SEEM to be poisonous.\n\nYour training in the culinary arts has presented you with some strange ingredients before, but this one is particularly inspiring. Perhaps someone within the  Azurewing Repose can suggest a preparation for Leyblood.", objectives = "Obtain 3 vials of Leyblood, then bring them to Cedonu in Azurewing Repose.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38868] = { id = 38868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Ruins of Kra'nak" }
quests[38869] = { id = 38869, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Ruins of Kra'nak" }
quests[38870] = { id = 38870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleeding the Bleeding Hollow" }
quests[38871] = { id = 38871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bleeding the Bleeding Hollow" }
quests[38872] = { id = 38872, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Lady's Bidding", description = "Uh, are these guys friendlies? I guess it's a good sign they haven't tried to eat Duchess... yet.\n\nAnyway, I have orders. Nathanos caught up with the dark rangers, who were sent forward aboard the Oblivion on a secret mission from Lady Sylvanas herself! Unfortunately the Alliance caught wind of our plan, and now Greymane is attacking the outpost!\n\nWe could really use you over there, {name}. Duchess can take you there, just give me the word.", completion = "Finally someone competent arrives at this sorry excuse for an outpost. \n\nOur efforts to complete Sylvanas's mission are at a standstill, but now we have even more pressing matters on our hands.", objectives = "Meet with Nathanos Blightcaller in Dreadwake's Landing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38873] = { id = 38873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clear the Deck!", description = "Our mission in Skold-Ashil will have to wait, {class} - for now, we have more pressing matters to attend to.\n\nI had just recently arrived with reinforcements for our assault when Greymane's ship sailed in and began barraging our walls. We deployed our siege weapons, but their ground forces quickly overwhelmed us.\n\nIf you can get to those catapults and take out the dogs manning the cannons, it may give us the window we need to push the attack!", completion = "Hah! Greymane will find his cannons aren't so useful when the blight takes his crew!", objectives = "Fire 4 Forsaken Catapults in Greymane's Offensive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38874] = { id = 38874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "BAD" }
quests[38876] = { id = 38876, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Fel Forge", description = "The Iron Horde continue to bring in reinforcements from all over Draenor to reinforce their position at Hellfire Citadel. If we don't cut off the flow of supplies then we risk losing control of our plans in Tanaan.\n\nA strategic attack to the supply lines at Ironhold Harbor is just the thing to keep the Iron Horde on the defensive and maintain our momentum.", objectives = "Assault the Iron Horde reinforcements at Ironhold Harbor in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38877] = { id = 38877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Fel Forge", description = "The Iron Horde continue to bring in reinforcements from all over Draenor to reinforce their position at Hellfire Citadel. If we don't cut off the flow of supplies then we risk losing control of our plans in Tanaan.\n\nA strategic attack to the supply lines at Ironhold Harbor is just the thing to keep the Iron Horde on the defensive and maintain our momentum.", objectives = "Assault the Iron Horde reinforcements at Ironhold Harbor in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38878] = { id = 38878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shielded Secrets", description = "Our goal lies within that vault, {class}. I don't have time to explain in detail - just know that it is vital to the Forsaken that we succeed.\n\nThe shieldmaidens have proven tenacious in their defense, but I believe there may be another way in. A chosen few of their order are allowed entrance, and I need you to find out how.\n\nIn the town I have seen intricately engraved shields which I believe are passed down from these champions. The scenes they depict may be the key to passing into the vault.", completion = "I would hope that you bring me some good news, {class}. \n\nFor both of our sake.", objectives = "Examine 6 Engraved Vrykul Shields in Skold-Ashil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38882] = { id = 38882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Life for Undeath", description = "It seems that you are full of surprises, {name}. With the blessing of the Valkyra queen, you have opened a path that will shape the destiny of Azeroth.\n\nI invite you to bear witness, for today a new day dawns on the Forsaken!", completion = "It looks like we underestimated Greymane's tenacity - a mistake that cost the Forsaken dearly. \n\nThis Eyir cannot hide for long, however. If I must I will hunt her through the Halls of Valor! \n\nGo now, {class}. I will call upon you when you are needed.", objectives = "Follow Sylvanas into the Vault of Eyir.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38885] = { id = 38885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shivering Ashmaw Cub" }
quests[38886] = { id = 38886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 021 - Sleeper's Barrow - twh" }
quests[38887] = { id = 38887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Bluffs - Vignette: Swiftflight - TRACKING - twh" }
quests[38888] = { id = 38888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Highmountain Tauren", description = "Ye've brought me a bit of interesting rocks to look at, {name}. I've got a special assignment for ye, if ye're up for it.\n\nI hear stories about these tauren, up in Highmountain, who claim mastery over minin'. I don't know if they're as talented as you or me, but they've been minin' leystone longer.\n\nPay 'em a visit. See what they have to say.", completion = "You are indeed a miner. You have the look of it. There is ore in your blood.", objectives = "Report to Ronos Ironhorn in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38889] = { id = 38889, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Adopting the Adorable", objectives = "You kneel down and hold out a hand. The baby bear sniffs at your fingers, looking up at you trustingly.\n\nThis bear cub is too little to fend for itself. Will you take it with you on your travels?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38890] = { id = 38890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Dead Yet!", description = "They're not dead yet! A little nitro here, a jolt of electricity there... we can bring 'em back! And then, they can pay me! Whaddya say, {name}? Wanna go into business with me?", objectives = "Use the Nitro-Electric Jumpstarter to resurrect 5 Gadgetzan Bruisers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38892] = { id = 38892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting Report", description = "We were supposed to meet back here, and then sneak back to Gatgetzan. That was hours ago, {name}! The others fanned out across all of Tanaris to gather intel.\n\nAnything you can find will help in the defense of Gadgetzan. Keep your eyes open, {name}!", objectives = "Find Goblin Intel from any Steamwheedle Scout in Tanaris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38893] = { id = 38893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 022 - Whispering Bluffs - twh" }
quests[38894] = { id = 38894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Founded Garrison" }
quests[38895] = { id = 38895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Vignette: Swiftflight - Treasure001 - twh" }
quests[38896] = { id = 38896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tearing down the Legion", description = "A piece of paper is tacked to the controls. On it is a tally of demons slain by the previous pilot.\n\nYour ego demands satisfaciton.", objectives = "Kill 15 Legion Invaders while piloting a vehicle during a Tanaris invasion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38900] = { id = 38900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Bluffs - Vignette: Nightcaller - TRACKING - twh" }
quests[38901] = { id = 38901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Felsmiths", description = "Ye have a knack with this felslate, <lad/lass>. Best ship ye off to someone who knows the stuff better than I.\n\nThe Illidari have a knack with all things demonic, really, and I've heard about a few miners who've set up shop out near the demons in Suramar.\n\nPay 'em a visit. See what they have to teach ye.", completion = "You want to mine felslate?\n\nDo you really think you have what it takes?\n\nAre you willing to make sacrifices?\n\nGood.", objectives = "Report to Felsmith Nal'ryssa in Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38902] = { id = 38902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Coruscating Bloom" }
quests[38903] = { id = 38903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Bluffs - Vignette: Nightcaller - Interaction - TRACKING - twh" }
quests[38904] = { id = 38904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Broken Shore", description = "Fear not, {name}. I'm angry, but I don't chase my own death.\n\nWe will fly in and scout the ideal point of attack. The demons are still drunk on their victory, but we will put a swift end to their revelry!\n\nTake my spare mount and we will fly to the Broken Shore. There we will bring honor to our dead.", completion = "Welcome to Skyhold, hero. Normally one must die to gain entrance, but times have changed.", objectives = "Take Saurfang's spare mount to the Broken Shore and fight alongside him to restore your honor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38906] = { id = 38906, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Rescue", description = "Saurfang, Wyrmsbane, and Anselm could not wait for reinforcements, they have ventured into that mess to cut off the heads of demon captains. I'm sure they do not require help but time is of the essence.\n\nIf you could go and assist them in killing the demon captains, we can get on with killing the portal guardian.", objectives = "Assist the warriors in killing the demon captains in the Fel Ingress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38907] = { id = 38907, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keepers of the Hammer", description = "The Highmountain Tribes had intended to pledge our allegiance to your forces. We know war has come with the Burning Legion.\n\nHowever, we have been betrayed from within and must now ask for your aid.\n\nA great relic, the Hammer of Khaz'goroth, was stolen from our people by the vile drogbar.\n\nWe need your help in recovering it.", progress = "We must be swift. I was overlong in finding you.", completion = "I know you seek the Pillar of Creation but I am sad to say it was one of many things we lost today.", objectives = "Meet Mayla Highmountain at Thunder Totem in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38909] = { id = 38909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get to High Ground", description = "It is no accident that Dargrul attacked the Rivermane in force. It is their farms and their pastures that supply food for the region.\n\nPlease, get Jale to Thunder Totem. With luck, Mayla will have reinforcements to send to the area.\n\nWe will rally the survivors here and follow as quickly as we can.", progress = "Have you had any luck with the Rivermane?", completion = "Riverbend was... destroyed? That disgusting beast Dargrul! I will not stop until I see him dead.\n\nBut we cannot do that with the army we have.\n\nWe need help from the other tribes.", objectives = "Bring Jale Rivermane to Thunder Totem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38910] = { id = 38910, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rocs vs Eagles", description = "High Crawliac has taught her witches how to curse our beloved eagles into the vile rocs you see assaulting the valley.\n\nThere is no way to break this curse once it has taken hold.\n\nWe will take to the skies and do battle with the rocs, but we need your help on the ground.\n\nHead north through Darkfeather Valley and release any eagles that you find.\n\nEvery eagle you save is one less roc we must kill later.", completion = "Your bravery has returned to us some of our fine feathered friends. Well done.\n\nNow how do you feel about a frontal assault?", objectives = "Save 7 Captive Great Eagles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38911] = { id = 38911, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rivermane Tribe", description = "What has happened here requires more time than I have to explain. In short, our tribes have scattered in the wake of the attack that left the Hammer of Khaz'goroth in the hands of the barbaric drogbar.\n\nEven now the drogbar are raiding the Rivermane tribe, and I have too few braves left to send to their aid. \n\nWe need a hero. Please, go to Earthmother's Bounty and lend what aid you can.", completion = "Mayla was still able to send help? I could hug that child.\n\nWelcome, outsider. I am Jale Rivermane, Chieftain of the Rivermane tribe. And we could really use your help.", objectives = "Meet Jale Rivermane at Earthmother's Bounty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38912] = { id = 38912, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloodtotem Tribe", description = "The Bloodtotem are led by Torok, a volatile but useful tauren chieftain. He is wary of outsiders, but I believe you have already met an emissary to their tribe--Oakin Ironbull--whom you rescued at Riverbend.\n\nUse that small thread and you may be able to bring the Bloodtotem back into the fold. Highmountain needs them if we are to defeat the drogbar and reclaim the Hammer of Khaz'goroth. Be on your guard, {name}.", completion = "Outsider, you are one of few from beyond Highmountain who has made it into these woods alive. With me vouching for you, the Bloodtotem have been given a no-kill order by Torok.", objectives = "Meet Oakin Ironbull at Cliff's Edge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38913] = { id = 38913, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Skyhorn Tribe", completion = "Ha ha! And what are you, tiny creature? Have you come to battle us or join us in battle?", objectives = "Meet Lasan Skyhorn at Skyhorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38914] = { id = 38914, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of Highmountain", description = "Now that you are familiar with our greatest hero, perhaps you are willing to assist me on a very dangerous endeavor.\n\nTo this end I have sent word for one of your allies to join us.\n\nWhen you are ready, join us in my spirit lodge. It is up the elevators and across the southwestern most bridge.", sourceObjective = "Speak with Spiritwalker Ebonhorn in Thunder totem.", sourceObjectiveStatus = "unverified-source-field" }
quests[38915] = { id = 38915, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of Snowblind Mesa", description = "Your timing is fortunate. Our forces at Snowblind Mesa report seeing the Underking above ground.\n\nWhat is more, he is lightly guarded, and has the hammer with him. Thanks to your efforts, we can meet them in battle.\n\nMeet us at Snowblind Mesa and let us take the fight to Dargrul together.", completion = "That... is a lot of drogbar.", objectives = "Journey to Snowblind Mesa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38916] = { id = 38916, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of Highmountain", description = "Mayla's father, Ulan, was our last high chieftain. He was slain trying to stop the Underking from seizing the Hammer of Khaz'goroth.\n\nI have watched Mayla all her life and can tell you she has both the courage and the strength to wear the mantle of High Chieftain.\n\nShe needs only our help to realize it herself.\n\nWill you meet us at the city entrance along the southern bluff? There is a ritual that might help, but we will need your aid to survive it.", completion = "Ah, thank you for coming. Mayla is as stubborn as her father if not more so.", objectives = "Meet Spiritwalker Ebonhorn at the southern bluff of Thunder Totem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38922] = { id = 38922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Littlefur", description = "Stranger, I beseech you! My once peaceful brethren are now cursed with insatiable wrath.\n\nMy nephew and I tried to leave against the Chieftain's wishes. The clan wrested him from me, and would have torn me apart if I did not flee.\n\nHe is trapped in the village, and I fear the worst.\n\nGreat {class}, please save him. I am too old and too weak to do it myself.", completion = "Uncle?", objectives = "Speak to Littlefur at Smolderhide Thicket.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38923] = { id = 38923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashran Dominance", description = "The Alliance refuse to back down in Ashran. Teach them that the Horde will not stand aside while they plunder the power of the ancient ogre empire to use for their own schemes.", progress = "COMMANDER! GOOD SHOWING OUT THERE!", completion = "NICE WORK. TOO BAD THE ALLIANCE IS STILL BEATING DOWN OUR GATES! GET BACK OUT THERE!", objectives = "Defeat the enemy faction at the event locations in Ashran and slay their leader within their base.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38924] = { id = 38924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Continue the Domination", description = "The Alliance refuse to back down in Ashran. Teach them that the Horde will not stand aside while they plunder the power of the ancient ogre empire to use for their own schemes.", completion = "NICE WORK. TOO BAD THE ALLIANCE IS STILL BEATING DOWN OUR GATES! GET BACK OUT THERE!", objectives = "Defeat the Alliance at the event locations in Ashran and kill Grand Marshal Tremblade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38925] = { id = 38925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashran Dominance", description = "As we feared the Horde are trying to consolidate their position here on the island by looting it, just like we feared. Get out there and show them the Alliance won't put up with their aggression.", completion = "Well done. That will give the Horde something to think about next time they decide to test us here in Ashran.", objectives = "Defeat the enemy faction at the event locations in Ashran and slay their leader within their base.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38926] = { id = 38926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Continue the Domination", description = "As we feared the Horde are trying to consolidate their position here on the island by looting it, just like we feared. Get out there and show them the Alliance won't put up with their aggression.", completion = "Well done. That will give the Horde something to think about next time they decide to test us here in Ashran.", objectives = "Defeat the Horde at all event locations in Ashran and kill High Warlord Volrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38927] = { id = 38927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Hardened", description = "Defeat your opponents on the battlefield and you will be rewarded.", objectives = "Win 3 Rated Battleground matches.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38929] = { id = 38929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle Hardened", description = "Defeat your opponents on the battlefield and you will be rewarded.", objectives = "Win 3 Rated Battleground matches.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38931] = { id = 38931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hero's Call: The Hinterlands!", description = "By order of his royal highness, King Varian Wrynn, all able-bodied citizens of the Alliance are to report to Gryphon Master Talonaxe at the aviary in Aerie Peak.\n\nOur new brothers in the Alliance need your help to fend off the aggressive Horde offensive in their beloved homeland. Travel north from the Arathi Highlands, through the dwarven mountain pass and follow the road northwest to Aerie Peak.\n\nFor the glory and honor of the Alliance!", sourceObjective = "Travel to Aerie Peak in The Hinterlands and speak with Gryphon Master Talonaxe.", sourceObjectiveStatus = "unverified-source-field" }
quests[38932] = { id = 38932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Equipment Blueprint: Bilge Pump", description = "This appears to be a blueprint for some sort of naval equipment.  We should take it back to our Shipyard and see if someone can decipher it.", progress = "Those look like some equipment blueprints!", completion = "This is a blueprint for some high tech naval equipment.  I should be able to reverse engineer the plans and have this equipment available for you shortly!", objectives = "Return the blueprints to a Naval Equipment Specialist at your garrison shipyard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38933] = { id = 38933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Logistical Matters", description = "I think we are ready to... reintroduce ourselves to the Legion on the Broken Isles.\n\nLord Grayson Shadowbreaker has volunteered to help coordinate our forces on the ground. You should speak with him immediately, Highlord.", completion = "Now is the time to strike back against the Legion.", objectives = "Speak to Lord Grayson Shadowbreaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38934] = { id = 38934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silas' Secret Stash", description = "A great Darkmoon prize do you now seek, but be ye warned, it is not for the meek.\n\nYour very first clue to send you on this caper, you will find printed on the back of this paper.", objectives = "Find Silas' Secret Stash.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38935] = { id = 38935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "His Name Was... Stormstout", description = "The land is ripe with rumors of an unusual pandaren monk whose power was matched only for his appetite for brew.\n\nHe was traveling with his young niece who's mouth seems to get them into a lot of trouble.\n\nThe locals say these two were headed to the Valley of the Four Winds. You should meet him! Just... watch out for that right hook.", completion = "Ha ha! You were sent by Bolo? The \"Keg Mender,\" right? From the Drunken Hozen?\n\nHow is his eye healing? Is his friend still hung over?\n\nAhh... that was an enjoyable evening.", objectives = "Speak with Chen Stormstout at the Thunderfoot Fields in the Valley of the Four Winds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38936] = { id = 38936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Road to Kun-Lai", description = "Lorewalker Cho has sent word that several of your companions survived the conflict in the Jade Forest and have been moved to Kun-Lai Summit to seek healing.\n\nThey need your help if they are to survive!\n\nTo reach Kun-Lai Summit, travel to the Valley of the Four Winds and look for the Highroad Grummle that can be found at the base of the Veiled Stair along the northeastern border.\n\nThey can guide you the rest of the way.", completion = "Oh, you are a friend of Cho's? Welcome! Welcome!\n\nI would serve you a banquet, but as you can see, we are in dire straights at the moment.\n\nSay, would you be willing to lend us a hand?", objectives = "Travel through the Veiled Stair to Binan Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38938] = { id = 38938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbearable", description = "Not far away, a bear cub looks to be in some distress. Perhaps you should investigate?", objectives = "Investigate the Shivering Ashmaw Cub in southern Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38939] = { id = 38939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Skold-Ashil", description = "<insert>" }
quests[38940] = { id = 38940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Mission Complete" }
quests[38943] = { id = 38943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Val'sharah - Treasure 023 - Moonclaw Vale - twh" }
quests[38944] = { id = 38944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sew It Begins", description = "Every time Dalaran takes us to a new shore, I get anxious over what types of fabric and cloth we might find below.\n\nThreads imbued with magic? Something demonically-tinged?\n\nUgh, I hope it's not FURS again.\n\nYou're an adventurer... and tailor to boot. Head on down there and see what you can scrounge up!", progress = "I wouldn't mind working with some cashmere...", completion = "Now this... this I can work with!\n\nReminds me of some old night elven festival cloth I've seen.", objectives = "Obtain 10 Shal'dorei Silk. You can find Shal'dorei Silk on humanoids within the Broken Isles, obtain some from a fellow adventurer, or you may visit the Auction House and buy some.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38945] = { id = 38945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Should Be Simple... Right?", description = "I have plenty of silk patterns that we can put this cloth to work on.\n\nHelp me to prepare the materials, {name}. We're going to put this cloth to good use and make you a new robe.", progress = "We're back in business again. How exciting!", completion = "That's a shame. Without the ability to do any stitching, we can hardly do anything with this fabric.\n\n<Tanithria pouts.>\n\nStill, there ARE patterns we know that don't require stitching. Shoulderpads are easy, and belts should be a cinch.", objectives = "Craft a Handcrafted Silkweave Robe on Tanithria's Finishing Bench. You can find the pattern in your tailoring pattern list. You can find the materials for the pattern in her shop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38946] = { id = 38946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consult the Locals", description = "Whoever wove this fabric CAN'T have intended it only for belts and shoulderpads. There must be some way to sew thread into this material.\n\nHead on down to Azsuna and try to find a tailor. We need to sew if we're going to do any real tailoring.", completion = "My my, look at you! Such an attractive young {class}, and all bedecked in magical finery and weaponry. To what do I owe the pleasure?\n\nAha! Tailoring! It's your lucky day, er...\n\nI'm sorry, what was your name? {name}?\n\nIt's your lucky day, {name}! I happen to be one of the best tailors in Suramar...", objectives = "Find a tailor in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38947] = { id = 38947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runic Catgut", description = "Let me guess... thread troubles? Mm-hm.\nI suspected as much. My people weave sumptuous silks, but those silks can be fickle about the types of thread they'll accept.\n\nShal'dorei silk has a bit of ley energy woven right into it. You need something that's learned to coexist with the ley energies of this land.\n\nI'm talking about owlcats, my good friend! They have what you need. You'll find them amongst the ruins of Llothien.", progress = "They are quite remarkable creatures, really. I used to keep one as a pet and mount... but that was a lifetime ago.", completion = "Perfect. Marvelous!", objectives = "Obtain 3 pieces of Runic Catgut.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38948] = { id = 38948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hard Times", description = "When I worked at the tailoring guild in Suramar, I would usually work off of a pattern. Something that inspired me.\n\nUnfortunately, I've run into streak of bad luck, and I'm ashamed to say that I no longer have my patterns.\n\nThe naga sorceresses in the lagoon to the west, however, have expertly-sewn wristwraps. And the nightfallen to the north wear robes that we can use... if you can pry one from their greedy clutches.", progress = "What've you got in your hands, there?", completion = "You, {name}, are a person of great skill. I send you out for patterns, and you do so without question. Remarkable!", objectives = "Obtain a Stained Silken Robe and a set of Hatecoil Wristwraps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38949] = { id = 38949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "So You Think You Can Sew", description = "Very good, I think we're ready to begin.\n\n<Lyndras steals a glance at your powerful weapon. A look of hunger washes over his face before he shakes it off and continues.>\n\nLet's prepare our materials and make the robe and bracers that you so rightfully deserve!", progress = "You're pretty lucky to have found me.", completion = "There you have it!\n\nNo, no, don't thank me. I'm just happy to have been of service.", objectives = "Craft a Rune-Threaded Silkweave Robe and a set of Rune-Threaded Silkweave Bracers at Lyndras' Finishing Table. You can find the patterns in your tailoring pattern list.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38950] = { id = 38950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wayward Tailor", description = "Might I ask a favor, {name}?\n\nAs I am recently without a home, shop, family, or friends, I was wondering if you might show me your floating city? I must admit, I am VERY curious about the place. I've also heard good things about their tailoring shop.\n\nI have no way of getting there myself, but certainly such a magical city has SOMEONE who can summon me.\n\n<Lyndras looks at you with hopeful apprehension.>", progress = "Did you find a tailor yet?", completion = "Your friend certainly has an... interesting appearance.\n\nHe taught you to sew this silk? Hmm. Maybe we should keep him around for a while.", objectives = "Speak to Lalla Brightweave in Dalaran, and ask her to summon Lyndras.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38951] = { id = 38951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Needle Need", description = "This shop has almost everything we need. Unfortunately, the quality of your sewing needles is lacking.\n\nI do know where you can get better needles. The sprites of Val'sharah are covered with spines which, fortuitously, are perfect for the type of sewing we need.\n\nI hate to be such a prickler stickler, but these needles really will make a difference.", progress = "Your friend thinks these needles will make a difference?", completion = "Hmm... he may have a point.\n\nThese needles ARE quite strong, and they have a nice bounce to them. Still, I do take issue with their shape and feel. I have an idea.", objectives = "Obtain 150 Spritethorns.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38952] = { id = 38952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meticulous Precision", description = "The needles are sharp, but look at them closely. Some have a curve to them, others have a spur hanging off the side. Look at this one... it's got a ninety-degree crook in it! I have no desire to sew around a corner.\n\nTiffany Cartier in the jewelcrafting shop has a good eye for this sort of thing. Bring these needles to her, and she'll straighten them out.", progress = "What's this, {name}?", completion = "Look at these! Strong, light, flexible, sharp, with a refined curve and a smooth edge. You've certainly put your Dalaran touch on it. It's the best of both worlds!\n\nEnough fussing over our tools, now. Shall we sew?", objectives = "Bring the Spritethorns to Tiffany Cartier in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38953] = { id = 38953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Advanced Needlework", description = "You've already learned the patterns for bracers, belts, epaulets, and of course, robes. Unfortunately, your technique was wasteful... you need a better method.\n\nThat's where our needles come in.\n\nHere, I'll show you how to improve the process of these patterns.", progress = "Keep your eye on your needlework. Don't lose focus now.", completion = "Now isn't that just lovely. Go on, try it out yourself!", objectives = "Make an Embroidered Silkweave Robe on Tanithria's Finishing Bench. You will need to gather the materials in her shop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38954] = { id = 38954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where's Lyndras?", description = "That's strange. Lyndras was here one moment, and then he ran off the next. He had such a strange look on his face.\n\nPerhaps we should track him down.", completion = "Sorry about that, {name}. You caught me snooping around. I suppose my curiosity got the better of me.\n\nAllow me to make it up to you.", objectives = "Find Lyndras.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38955] = { id = 38955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sew Far, Sew Good", description = "Your tailoring skill really is impressive and, although I don't have my patterns with me, I do have some patterns memorized. One of those patterns is for a simple bag.\n\nFollow my lead, {name}.", progress = "There's nothing quite like a new bag.", completion = "There you have it. Not the best bag in the world, but it's better than most.\n\nI want to apologize again for running off, {name}. My hunger... err, curiosity... occasionally gets the better of me. I promise it will not happen again.", objectives = "Craft a Silkweave Bag. You will need to gather materials inside the Dalaran tailoring shop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38956] = { id = 38956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where's Lyndras Again?", description = "Oh dear.\n\nHe had just promised you that he wouldn't wander off, and then he did it again!\n\nI'm starting to think that this Lyndras character might be a bit too impetuous for my tastes.\n\nPlease, go find him, before he gets into any more trouble.", completion = "My most sincere apologies, {name}. Not only did I make a spectacle of myself, I fear I may have also put the good name of your tailoring shop at risk.\n\nYou have every right to be upset with me.", objectives = "Find Lyndras in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38957] = { id = 38957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking Inspiration", description = "I wish I had more patterns to share, but my notebook was lost along with my shop. We'll need to come up with some patterns on our own.\n\nI've been thinking about the leather breeches that the Stormheim vrykul wear. They're certainly much thicker and heavier than anything we could sew, but their embellishing runework is quite impressive.\n\nIf I had a few pairs, perhaps I could re-imagine this runework on a more... refined garment.", progress = "I'm looking forward to this.", completion = "Aha! This will be much simpler than I'd first thought.\n\n<Lyndras takes a moment to jot some instructions down on a scrap of vellum.>\n\nHere, {name}. You should have it.", objectives = "Obtain 6 Runed Breeches.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38958] = { id = 38958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Right Color", description = "Your assistance, {name}, if you have a moment.\n\nI've been attempting to reproduce a pattern for footwear that I spotted a while back, but I'm having trouble getting the right color for my dye. Our black dye is too dark, our blue dye is too bright, and mixing the two doesn't look right.\n\nThe color I'm looking for is more of a squid-ink blue. If, in your travels, you come across any dyes of this color, would you do me the favor of bringing some to me?", progress = "I'm quite close to completing these slippers.", completion = "Marvelous!", objectives = "Obtain 10 Helsquid Ink.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38959] = { id = 38959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Left Behind", description = "I do truly want to help you work on your tailoring, but without my patterns or my supplies, there isn't much more I can do save for teaching you what little I remember.\n\nIf my memory still serves true, you're just missing a good pattern for some gloves and a hood.\n\nThe first thing I need you to do is grab a few things from where you first met me. Here's what I need...", progress = "I had no clue I'd be magically teleported here, otherwise I would have gathered my things myself.", completion = "Excellent! It's always nice to have familiar things.\n\nThis will make instructing you much easier for me.", objectives = "Gather Lyndras' Pinking Shears, his Box of Measuring Tools and his Threading Needles from where you first met him in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38960] = { id = 38960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lining Them Up", description = "Since you're heading to Azsuna, you may as well gather some lining for our projects.\n\nThe bears of Azsuna are known for how soft, yet durable their fur is.\n\nHunt them in the woods around Llothien and bring their fur back with you.", progress = "Don't take them for easy prey. They're as vicious as they are cunning.", completion = "This will be plenty.", objectives = "Gather 15 Bear Furs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38961] = { id = 38961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye of Azshara: The Depraved Nightfallen", description = "In order to craft the gloves, we'll require a special item. This will be no easy task to recover it, {name}.\n\nThe naga of Azsuna are said to be hard at work trying to summon a terrible creature into this world.\n\nThe creature's heart holds immense energy that we can use to channel into the gloves, making them incredibly powerful.\n\nI need... I mean, we need that heart if we are to produce a suitable pair of gloves for someone of your presence.", progress = "What were you able to find?", completion = "Lyndras ran off again before you could return, {name}. He left a note and a pattern for you.\n\nThe note reads,\n\n\"I'm sorry, {name}, but I'm afraid I may become a threat to the fellow tailors of this shop. I'm off to find somewhere to try and control my urges, or fall into depravity. It has been an honor training you.\n\nSincerely,\n\nLyndras\"\n\nHow sad...", objectives = "Go to the Eye of Azshara, defeat the Wrath of Azshara and recover the Heart of the Storm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38962] = { id = 38962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Path to Suramar City", description = "I recall Lyndras mentioning a guild of tailors within Suramar City. Perhaps they could further our understanding of how to utilize this new cloth.\n\nUnfortunately from what I've heard, they've sided with the demons and anyone opposed to them is to be killed on sight.\n\nYou must find a way to move safely within the confines of their city if we're to continue our research.", completion = "Now that you can move safely around the city, it's time to find some new masters.", objectives = "Assist the nightfallen of Suramar until you discover a way to move safely amongst the elves of Suramar City.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38963] = { id = 38963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Lesson?", description = "Now that we have everything we need, let's work on the hood.\n\nAfter we're finished, we'll move onto the gloves.", progress = "Come now, {name}. Let us sew.", completion = "Well done, {name}. Before long you may be the one teaching me a thing or two.", objectives = "Create a Handcrafted Silkweave Hood on Tanithria's Finishing Bench. You will need to gather the materials in her shop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38964] = { id = 38964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where's Lyndras Now?", description = "Lyndras couldn't have gone very far. I mean, we're floating a thousand feet over the sea. \n\nI heard some commotion across the way this morning near the alchemy shop. I pray that wasn't Lyndras.\n\nCould you please go over there and make sure?", objectives = "Go the alchemy shop across the street.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38965] = { id = 38965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Violet Hold: Into the Hold", description = "With Lyndras being locked up in Violet Hold, you feel responsible for him and must discover the truth behind his actions.\n\nPerhaps if you were able to speak with him, you could find a way to have him released from the hold and put back into your custody.\n\nGo into Violet Hold and find out what happened to Lyndras.", progress = "Did you discover what happened to Lyndras?", completion = "<Tanithria listens to your account of Lyndras' fate.>\n\nI... I see. That's a shame.\n\nI had grown to enjoy his company, you know. If you'll excuse me, I need a moment to think about him.", objectives = "Go into Violet Hold and find out what happened to Lyndras.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38966] = { id = 38966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secret Silkweaving Methods", description = "Okay, done mourning! Let's look through his stuff.\n\n<Tanithria takes a moment to leaf through Lyndras' journal. Her eyes open wide.>\n\nOur friend has been keeping secrets from us. Look at this! Every single one of the recipes he's taught us can be improved.\n\nLet's start simple, with some bracers. I can supply most of the materials, but you'll have to talk to Alard Schmied in the blacksmithing shop to get this powdered brimstone.", progress = "These patterns are fascinating. I never knew you could get this kind of result out of simple silks.", completion = "The good news is that we can now craft more efficient patterns out of silkweave.\n\nThe bad news is that we've expended the remainder of Lyndras' knowledge. Where should we turn next?", objectives = "Craft some Masterwork Silkweave Bracers.\n\nYou will need to gather materials from the Dalaran tailoring shop and blacksmithing shop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38967] = { id = 38967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nightborne Connection", description = "Now that you're able to disguise yourself, you should go to Suramar City and try to find this guild of tailors.\n\nGood luck, {name}, and try not to get caught.", completion = "Ah, a fellow tailor. Pleasure to make your acquaintance, uh... {name}, was it?\n\nI trust you'd like to come into the fold of our guild? Where did you receive your prior training?", objectives = "Speak with Leyweaver Tytallo in Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38968] = { id = 38968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Loyalty", description = "<Tytallo listens as you recount what happened with Lyndras.>\n\nI see. You sound almost... sympathetic to the wretch.\n\nThe nightfallen are liars and thieves. ALL of them. Lyndras included.\n\nI will not tolerate a student that has any respect or sympathy for those... things. And have you witnessed what they turn into at the depths of their depravity?\n\nIf you want to get on my good side, do not return until you are covered in the blood of the withered.", progress = "If you wish to earn my tutelage, you must first prove that you are on our side.", completion = "Hmm.\n\nVery well. We may continue.", objectives = "Slay 25 withered within Suramar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38969] = { id = 38969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Master of Silkweave", description = "While Tytallo is busy exacting withered genocide, it falls on me to take care of the more mundane aspects of training.\n\nWe're going to need to see how talented you are.\n\nCraft an entire set of silkweave armor for me. Leyweaver Mithrogane can provide you with a proper mannequin for displaying it.", progress = "If you wish to learn what we're about to teach you, you need a solid foundation.", completion = "Your stitching is still a little rough, but you've already mastered all of the basics.\n\nWell done.\n\nI don't say that very often. Savor it.", objectives = "Purchase a Shal'dorei Mannequin from Leyweaver Mithrogane, then craft an entire set of silkweave armor and place them on the mannequin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38970] = { id = 38970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Queen's Grace Loom", description = "Great power comes only with sacrifice. Even the most masterful tailor can only do so much with silkweave. To improve your patterns any further, bargains must be made.\n\nYou are prepared, {name}, to learn about working with Imbued Silkweave.\n\nUse the teleportation crystal behind me, and speak with Azayna, the leader of our order.", progress = "Return once you've spoken with Azayna.", completion = "Don't look at us that way, {name}. Selling our services to the demons may have been morally dubious, but our skills have grown exponentially since Azayna made the deal.\n\nContinue your training with us, or don't. If you want to leave now, nobody's stopping you. If you want to learn more... we are the only game in town.", objectives = "Use the Teleportation Crystal in the Leyweavers' Hall, then speak with Leyweaver Azayna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38971] = { id = 38971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exotic Textiles", description = "I'm risking my life and career to be here, tailor.\n\nI've been curious about demonic cloth, and my attempts to obtain some through approved means have been met with resistance.\n\nI simply must see this cloth for myself.\n\nI don't wish to disrupt Azayna's pact with the demons, but you - you can attack the demons without drawing attention to our guild.\n\nI'm particularly interested in a particular demon's set of robes. Bring me a scrap, and I'll teach you what I know.", progress = "Probably better that you fight the thing, anyhow. I'm useless with a weapon.", completion = "Excellent work. I will get to studying this fabric right away. As promised, I will teach you what I know. Are you acquainted with our patterns for gloves?", objectives = "Obtain the Fel Inscribed Shroud.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38974] = { id = 38974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Valor: The Right Question", description = "One might ask what a leyweaver is doing standing over a dead vrykul's body. But such questions only stir up trouble.\n\nInstead let us ask what can be learned from those who have passed on. A question like that promotes progress.\n\nI assume you're here to learn from me, the pattern for Imbued Silkweave pants, yes?\n\nIf that's true, then I'll need something from one who has passed on. In the Halls of Valor the great guardian, Hymdall resides.\n\nBring me his loincloth and I will teach you my pattern.", progress = "Asking the right questions will get you far.", completion = "<Tellumi takes the loincloth from you and gives you a sly smile.>\n\nI trust you now see looking at a situation from a functional angle than a reactionary one will earn you far more knowledge.", objectives = "Defeat Hymdall in the Halls of Valor and recover his loincloth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38975] = { id = 38975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inspire Me!", description = "I am, and always will be, a student of robemaking and dressmaking. You can keep your gloves, belts, and cloaks. Nothing beats a good robe.\n\nI'll share my pattern for an imbued silkweave robe with you if you can teach me some of the robe and dress patterns you've learned along your tailoring journey.", progress = "I never turn down the opportunity to learn a new robe pattern.", completion = "Not quite what I'd expected, but it was an interesting history lesson, at least. You can keep the robes, I've learned all I need just by watching you work.\n\nNow, as promised, I shall show you what I know.", objectives = "Craft a Brown Linen Robe, a White Woolen Dress, a Simple Black Dress, a Frostwoven Robe, and a Spiritmend Robe while standing near Leyweaver Mithrogane.\n\nIf you do not know a pattern, you can learn it from tailoring trainers in major cities.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38976] = { id = 38976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Undying Silkweave Bracers Crafted" }
