quests[38980] = { id = 38980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Undying Silkweave Gloves Crafted" }
quests[38981] = { id = 38981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Undying Silkweave Hood Crafted" }
quests[38982] = { id = 38982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Undying Silkweave Pantaloons Crafted" }
quests[38983] = { id = 38983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Undying Silkweave Robe Crafted" }
quests[38989] = { id = 38989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Orders, General?", description = "General, your forces in Tanaan Jungle await your orders. Travel to the Planning Map there to issue your commands.\n\nFor the Horde!", completion = "Lok'tar General. Your forces await your orders.", objectives = "Go to the Tanaan Planning Map in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38990] = { id = 38990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of Icecrown", description = "<A powerful presence again touches your thoughts.>\n\nI have ordered your brethren to Icecrown to prepare for the coming conflict, but I have a more important fate in mind for you. You, {name}, will be the hand of our vengeance!\n\nUse the Death Gate to return to Acherus and I shall reveal your role in this.", progress = "It is time to begin, {name}.", completion = "The Lich King made a wise choice in giving you those blades, {name}. You've more then proven yourself worthy of them.\n\nI have to admit though, I'm glad it wasn't me, I'm through with having magical weapons dictate my fate.", objectives = "Use your Death Gate ability to travel to Icecrown and obtain the Blades of the Fallen Prince.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[38992] = { id = 38992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mograine's Oath" }
quests[38993] = { id = 38993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Mission Sent" }
quests[38994] = { id = 38994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "TRACKING Encounter Botanist", description = "(PH)\nDarkgrove has run out of places to hide. Now it is time to finish him off.\n\nIf we stop him now, there may be hope for this valley yet.", sourceObjective = "Defeat Botanist Darkgrove", sourceObjectiveStatus = "unverified-source-field" }
quests[38996] = { id = 38996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Orders, General?", description = "Exarch Yrel has sent word from Lion's Watch in Tanaan Jungle that your forces stand ready for their new orders.\n\nFor the Alliance!", completion = "Greetings General. Your forces await your orders on the Planning Table.", objectives = "Speak with Yrel at Lion's Stand in Tanaan Jungle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39000] = { id = 39000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Don't Need No Library Card", description = "If history is any indication, Gul'dan is training a whole generation of warlocks to marshal against us. If we act fast, we can stem the tide and make things easier on ourselves.\n\nAs you and your fellow heroes venture into the depths of the Hellfire Citadel, seek out Tomes of Chaos from Gul'dan's lieutenants.\n\nThey're dangerous, so don't read any of them. Not even the pictures.\n\n<Khadgar shudders.>\n\nESPECIALLY the pictures.", progress = "What about those books, {name}?", completion = "<Khadgar gingerly looks over the spine of each book as you hand it to him, growing more and more visibly disgusted.>\n\nWill you look at these? This is like a set of encyclopedias for psychopaths.", objectives = "Collect 33 Tomes of Chaos from bosses in Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39001] = { id = 39001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Farahlon!", description = "{name}, have you ever heard of Farahlon? Archmage Vargoth would never stop talking about it - beautiful fields and forests dotted with natural crystalline formations that make it the magical nexus of Draenor. It's nearly impossible to get to. The magical storms in the seas around it are frequent and unpredictable.\n\nFor your ring, we'll need a magical artifact from Farahlon. You will need an absolutely top-notch crew to sail safely to the region and get back alive. Choose carefully and get me that artifact!", objectives = "Use your shipyard to complete the \"To Farahlon!\" Naval Mission and retrieve the Pearl of Farahlon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39002] = { id = 39002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogres of the Deep", description = "It might surprise you to know that at its peak the Gorian ogre empire had a small but powerful navy. It probably wouldn't surprise you to learn that many of its largest warships sunk. They were built out of stone.\n\nI've found an old chart indicating the last-known position of \"The Emperor's Foot,\" lost at sea with a valuable artifact I need. An ogre decoder.\n\nRight! To salvage it you'll need a submarine and a crack crew. This is an extremely dangerous mission which is why I'm giving it to you.", objectives = "Use your shipyard to complete the \"Ogres of the Deep\" Naval Mission and retrieve the Soaked Ogre Decoder.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39003] = { id = 39003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cooking the Books", description = "{name}, we've got to destroy these tomes. Many of them have actual tortured souls bound into the pages, so we can't just burn them. Cordana will know what to do.\n\nTake these books to my tower in Zangarra and give them to Cordana. Let me know when the deed is done.", progress = "<Khadgar smiles.>\n\nSo, how is Cordana doing? Is all well at my tower?", completion = "<Khadgar's face falls as you describe your encounter at the tower.>\n\nCordana...? Oh no no no...She's been very distant lately. I just... I thought it was part of her stone-cold warden routine. I didn't realize...\n\nAh, {name}! You see? This is exactly what Gul'dan does. He finds our weakness and turns it against us. Be careful who you trust. Ah, Cordana!\n\n\n\nCordana.", objectives = "Deliver Gul'dan's Library of Chaos to Cordana at Zangarra and ensure they are destroyed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39004] = { id = 39004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkness Incarnate", description = "We have one final task before us, {name}. We must defeat Gul'dan and unravel his plans for this world.\n\nI have no reward to offer you - I have given you everything I can.\n\nCome. When you and your allies are ready, we march on Hellfire Citadel... and end this.", progress = "We must thwart Gul'dan!", completion = "<Khadgar's face is ashen.>\n\nDraenor is saved, {name}. But the Legion is more powerful than even I had imagined. And Gul'dan, that snake - he's still alive. Somewhere.\n\nStay here and celebrate with the others, {name}. You've earned it. But I will soon return to Azeroth to deal with this, and I hope you will join me there when the time comes.", objectives = "Hunt down and engage Gul'dan within the Hellfire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39005] = { id = 39005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second Mission Sent" }
quests[39006] = { id = 39006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second Mission Complete" }
quests[39009] = { id = 39009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Third Mission Complete" }
quests[39010] = { id = 39010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Third Mission Sent" }
quests[39011] = { id = 39011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Black Rook Invasion", description = "Once, this area was peaceful and prosperous. Then we saw the first bad omens: strange ailments, spoiled crops, and the like. Now ghosts attack us from that castle across the river, and undead assassins slay our fishers so as to cut off the village's food supply.\n\nWe're the last family living this close to the castle, but we daren't retreat: this river is the best route for fishers to bring their hauls in to town. Please, will you take the fight to these undead?", objectives = "Kill 7 Black Rook Assassins in Bradensbrook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39015] = { id = 39015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grumpy", objectives = "<The puppy wags its tail furiously as soon as he spots you. He seems extremely grateful.>", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39017] = { id = 39017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise to the Occasion", description = "The Lich King made a wise choice in giving you that weapon, {name}.\n\nYou've proven your strength and cunning on countless occasions and it is time that you have a position fitting for your accomplishments.", objectives = "Speak with Highlord Darion Mograine within Acherus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39018] = { id = 39018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Archmage", description = "Archmage Khadgar has a very urgent favor to ask. He is gravely concerned about additional threats this world may hold for Azeroth, and he will need your assistance pursuing them. Please see him at his tower, east of Talador, in the Zangarra swamp.", completion = "<The Archmage looks damp and uncomfortable.>\n\nI apologize for the conditions here, {name}. I had no choice. I summoned this tower at the optimal confluence of arcane energies. My hope is to finish my work here before all my books get musty.\n\nSo then! Let's get to it.", objectives = "Speak with Archmage Khadgar at Khadgar's Tower in Zangarra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39019] = { id = 39019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Archmage", description = "Archmage Khadgar has devised the next course of action against the Shadow Council. Please see him at his tower, east of Talador, in the Zangarra swamp.", completion = "Welcome back, my friend. We have much work to do.", objectives = "Speak with Archmage Khadgar at Khadgar's Tower in Zangarra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39020] = { id = 39020, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Burning Path Through Time", description = "The blazing star shines upon the land, searing the earth and parching the landscape. This star is relentless, malevolent almost. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", progress = "Follow the blazing star, and walk the paths it reveals.", completion = "Ah, {name}, you have returned. An otherworldly air hangs heavy about you.", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39021] = { id = 39021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Frozen Path Through Time", description = "The chill star shines upon the land with its cold light as even the spirits retreat to the shadows. This star is unlike any other in the skies, sapping warmth and life. While its influence holds, new paths may open up, to distant places and even distant times. No sage truly understands the nature of this sign, but fortune favors the daring.", progress = "Follow the chill star, and walk the paths it reveals.", completion = "Ah, {name}, you have returned. An otherworldly air hangs heavy about you.", objectives = "Complete 5 Timewalking dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39022] = { id = 39022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Archmage", description = "Archmage Khadgar has devised the next course of action against the Shadow Council. Please see him at his tower, east of Talador, in the Zangarra swamp.", completion = "Welcome back, my friend. We have much work to do.", objectives = "Speak with Archmage Khadgar at Khadgar's Tower in Zangarra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39023] = { id = 39023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Archmage", description = "Archmage Khadgar has devised the next course of action against the Shadow Council. Please see him at his tower, east of Talador, in the Zangarra swamp.\n\nThis will not take long.", sourceObjective = "Speak with Archmage Khadgar at Khadgar's Tower in Zangarra.", sourceObjectiveStatus = "unverified-source-field" }
quests[39024] = { id = 39024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Archmage", description = "Archmage Khadgar has devised the next course of action against the Shadow Council. Please see him at his tower, east of Talador, in the Zangarra swamp.\n\nThis will not take long.", sourceObjective = "Speak with Archmage Khadgar at Khadgar's Tower in Zangarra.", sourceObjectiveStatus = "unverified-source-field" }
quests[39025] = { id = 39025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grasp of the Underking", description = "If we have one good fortune in this it is that Dargrul has no knowledge of how to use the hammer.\n\nHe keeps thinking of the hammer as a weapon instead of a tool of creation.\n\nEven so, he has imprisoned our tribesman in fists of stone summoned from the earth. Our weapons have proven useless against this magic.\n\nYou might have power enough to break these fists. Can you help?", progress = "How are the captives? Did you find them alive?", completion = "It has been an age or more since the drogbar last walked the surface in such numbers.\n\nThey became the dark stories we tell children.", objectives = "Rescue Jale Rivermane, Warbrave Oro, and Oakin Ironbull.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39026] = { id = 39026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Drogbar", description = "It wasn't enough for Dargrul to just destroy this village. He has also sent his Stoneraiders to take what is left.\n\nPlease champion, prove to my people that you are the hero I foresaw.\n\nSlay enough of these Stoneraiders that it breaks their resolve.", progress = "The drogbar were supposed to be our allies against the Burning Legion.", completion = "Your battle skills are impressive.", objectives = "Slay 8 Drogbar in Riverbend.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39027] = { id = 39027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dargrul and the Hammer", description = "We are about to follow a drogbar into a cave, something we warn our children never to do.\n\nEven so, several of our warbraves have already followed Dargrul inside.\n\nCome, join us in battle and let us reclaim the Hammer of Khaz'goroth.", progress = "This is a hard day.", completion = "Oro and the others? Did they make it out as well?\n\nSuch destruction. So many good warbraves have fallen today.\n\nIt is clear now, we will need the full might of the Highmountain tribes if we are to recover the hammer.", objectives = "Confront Dargrul the Underking.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39028] = { id = 39028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME", description = "asdf" }
quests[39029] = { id = 39029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defend The Temple" }
quests[39030] = { id = 39030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arauk Nashal 70:JP3 - Aggramar's Vault - Tracking Quest Cleared - God-King Intro" }
quests[39031] = { id = 39031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Ivory Sentinel" }
quests[39032] = { id = 39032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Summons from Saylanna", description = "Sprites have always been mischievous creatures, but lately their mischief has turned to violence.\n\nOne of the druids I call friend, Saylanna Riverbreeze, reports that they are assaulting the faerie dragon nesting grounds.\n\nThe Lunarwing Shallows lie to the south. You will find Saylanna there.", sourceObjective = "Seek out Saylanna Riverbreeze in the Lunarwing Shallows.", sourceObjectiveStatus = "unverified-source-field" }
quests[39033] = { id = 39033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Time to Strike", description = "This configuration of the stars causes an unusual vibration in the crystals strewn across Draenor, relics of the ancient Apexis. Some swear that the crystals will multiply when left unattended beneath the night sky, but none have seen the phenomenon firsthand. Regardless of the true cause, these crystals should be far more plentiful should you seek them out.", progress = "Ah, the unmistakable hum of crystals when the Apexis star shines....", completion = "Well done, {name}. Fortunately, a skilled diviner can use Apexis crystals to reveal oil deposits beneath the earth. I cannot teach you this art, but you may nevertheless reap its benefit.", objectives = "Complete 5 Objectives in Apexis-yielding areas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39034] = { id = 39034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emissary of War", description = "When the sign of the emissary shines in the night sky, the stars strengthen existing bonds and forge new ones. Friendship is still not cheaply won, and deeds will prove loyalty, but trust comes more readily during these days. Venture deep into caverns and strongholds to prove your worth.", progress = "Be bold, {name}, and you may win many friends on this day.", completion = "Your new allies left this here, as a tribute for your efforts on their behalf.", objectives = "Complete 4 dungeons on Mythic difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[39035] = { id = 39035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking: Horde Siegebreaker" }
